"use client";
import { useMorph } from "@/lib/sahajiv-motion/use-morph";
import * as React from "react";
import { cva } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { Button, type ButtonProps } from "@/components/ui/button";
import { useFlowGroup } from "@/lib/sahajiv-motion/use-flow";
import { IconButton } from "@/components/ui/icon";
const ButtonGroupContext = React.createContext<{
  value?: string;
  change: (value: string) => void;
} | null>(null);
export const buttonGroupVariants = cva(
  "v-seg inline-flex flex-wrap gap-[2px] p-[3px] [border-radius:999px] bg-[var(--card)] [box-shadow:none]",
);
export type ButtonGroupProps = Omit<
  React.ComponentProps<"div">,
  "defaultValue"
> & {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
};
export function ButtonGroup({
  ref,
  className,
  value,
  defaultValue,
  onValueChange,
  children,
  ...props
}: ButtonGroupProps) {
  const [local, setLocal] = React.useState(defaultValue);
  const flowRef = useFlowGroup<HTMLDivElement>(ref);
  const change = (next: string) => {
    if (value === undefined) setLocal(next);
    onValueChange?.(next);
  };
  const ownedMorphRef = useMorph<HTMLDivElement>("nav", flowRef);
  return (
    <ButtonGroupContext.Provider value={{ value: value ?? local, change }}>
      <div
        ref={ownedMorphRef}
        data-slot="button-group"
        data-part="root"
        data-togglegroup=""
        role="group"
        className={cn(buttonGroupVariants(), className)}
        {...props}
      >
        {children}
      </div>
    </ButtonGroupContext.Provider>
  );
}
export type ButtonGroupItemProps = ButtonProps & { value: string };
export function ButtonGroupItem({
  value,
  onClick,
  className,
  ...props
}: ButtonGroupItemProps) {
  const group = React.useContext(ButtonGroupContext);
  const pressed = group?.value === value;
  return (
    <Button
      data-slot="button-group-item"
      data-part="item"
      aria-pressed={pressed}
      data-state={pressed ? "on" : "off"}
      variant="ghost"
      size="sm"
      className={cn(
        "h-[36px] px-[14px] text-[13.5px] leading-none font-medium [border:0] [box-shadow:none] text-[color:var(--v-text-2)]",
        className,
      )}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented) group?.change(value);
      }}
      {...props}
    />
  );
}
export type ButtonGroupUtilityProps = React.ComponentProps<"div"> & {
  shapes?: boolean;
};
export function ButtonGroupUtility({
  className,
  shapes,
  ...props
}: ButtonGroupUtilityProps) {
  return (
    <div
      data-slot="button-group-utility"
      data-shapes={shapes ? "" : undefined}
      role="group"
      className={cn(
        "v-utility inline-flex gap-[2px] p-[3px] [border-radius:999px] bg-[var(--card)] [box-shadow:none]",
        className,
      )}
      {...props}
    />
  );
}
export type ButtonGroupUtilityItemProps = React.ComponentProps<"button">;
export function ButtonGroupUtilityItem({
  ref,
  className,
  ...props
}: ButtonGroupUtilityItemProps) {
  return (
    <IconButton
      ref={ref}
      data-slot="button-group-utility-item"
      type="button"
      className={cn(
        "v-ibtn inline-grid place-items-center [width:38px] [height:38px] shrink-0 [border-radius:50%] [background:var(--v-ink)] [color:var(--v-on-accent)] [box-shadow:none]",
        className,
      )}
      {...props}
    />
  );
}

@layer sahajiv-states {
[data-slot="button-group"] .v-btn {
  background: transparent;
  box-shadow: none;
  color: var(--v-text-2);
  border: 0;
}
[data-slot="button-group"] .v-btn:hover:not([aria-pressed="true"]) {
  background: color-mix(in oklab, var(--card) 84%, var(--v-ink));
  color: var(--v-text);
}
[data-slot="button-group"]
  .v-btn:is([aria-pressed="true"], .-on) {
  background: var(--v-ink);
  color: var(--v-on-ink);
}
[data-slot="button-group"].-pink
  .v-btn:is([aria-pressed="true"], .-on) {
  background: var(--v-pink);
  color: var(--v-on-accent);
}
[data-slot="button-group"] .v-btn .v-icon {
  width: 15px;
  height: 15px;
}
[data-slot="button-group"] .v-btn:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 1px;
  border-radius: 999px;
}
[data-slot="button-group-utility"]
  .v-ibtn:not([class*=" -"]):nth-child(3n + 1) {
  background: var(--v-blue);
}
[data-slot="button-group-utility"]
  .v-ibtn:not([class*=" -"]):nth-child(3n + 2) {
  background: var(--v-yellow);
}
[data-slot="button-group-utility"] .v-ibtn:not([class*=" -"]):nth-child(3n) {
  background: var(--v-pink);
}
.v-utility[data-slot="button-group-utility"] .v-ibtn.-ink {
  background: var(--v-ink);
  color: var(--v-on-ink);
}
[data-slot="button-group-utility"] .v-ibtn:hover {
  filter: brightness(0.92);
  z-index: 1;
}
[data-slot="button-group-utility"] .v-ibtn .v-icon {
  width: 18px;
  height: 18px;
  stroke-width: 1.9;
}
[data-slot="button-group-utility"][data-shapes] {
  border-radius: 17px;
  padding: 4px;
  gap: 4px;
}
[data-slot="button-group-utility"][data-shapes] .v-ibtn:nth-child(3n + 1) {
  border-radius: 14px 14px 14px 5px;
}
[data-slot="button-group-utility"][data-shapes] .v-ibtn:nth-child(3n + 2) {
  border-radius: 46% 54% 50% 50%/50% 46% 54% 50%;
}
[data-slot="button-group-utility"][data-shapes] .v-ibtn:nth-child(3n) {
  border-radius: 14px 5px 14px 14px;
}
:root[data-mode="dark"]
  :is([data-slot="button-group"], [data-slot="button-group-utility"]) {
  background: var(--v-beige);
}
:root[data-mode="dark"] [data-slot="button-group"] [data-glide-active] {
  color: var(--v-on-accent);
}

:root[data-mode="dark"] [data-slot="button-group"] .v-btn[aria-pressed="true"] {
  background: var(--v-pink);
  border-color: var(--v-pink);
  color: var(--v-on-accent);
}

}
